func academicWorkflowPaths() map[string]any {
	operation := func(summary string, params []map[string]any, body, result map[string]any) map[string]any {
		value := op(summary, params, body, response(200, summary, result))
		value["tags"] = []string{"AcademicWorkflows"}
		return value
	}
	body := func(name string) map[string]any { return jsonBody(refSchema(name), true) }
	datasetQuery := queryParams(param("query", "dataset_id", true, strSchema()))
	recordPath := queryParams(param("path", "expansion_id", true, strSchema()))
	return map[string]any{
		"/academic/document-states":                   map[string]any{"get": operation("Read document scholarly identity and current user's importance", queryParams(param("query", "dataset_id", true, strSchema()), param("query", "document_ids", false, strSchema())), nil, obj(prop("items", array(refSchema("AcademicDocumentStatus")))))},
		"/academic/documents/{document_id}/identity":  map[string]any{"patch": operation("Correct document identity or retry recognition", queryParams(param("path", "document_id", true, strSchema())), body("AcademicDocumentIdentity"), obj(prop("status", strSchema())))},
		"/academic/papers/{paper_id}/importance":      map[string]any{"put": operation("Set current user's personal importance", queryParams(param("path", "paper_id", true, strSchema())), jsonBody(objReq([]string{"dataset_id", "is_important"}, prop("dataset_id", strSchema()), prop("is_important", boolSchema())), true), obj(prop("is_important", boolSchema())))},
		"/academic/paper-selections:resolve":          map[string]any{"post": operation("Expand folders completely and resolve distinct confirmed papers", nil, jsonBody(objReq([]string{"dataset_id", "document_ids"}, prop("dataset_id", strSchema()), prop("document_ids", array(strSchema()))), true), obj(prop("papers", array(refSchema("AcademicWorkflowPaper"))), prop("invalid", array(obj(prop("document_id", strSchema()), prop("reason", strSchema()))))))},
		"/academic/workflow-launches":                 map[string]any{"post": operation("Idempotently start expansion or a separate downstream Chat", nil, body("AcademicTaskLaunch"), obj(prop("conversation_id", strSchema()), prop("expansion_id", strSchema()), prop("handoff_id", strSchema())))},
		"/academic/papers:search":                     map[string]any{"post": operation("Search external arXiv candidates and pin their versions to an owned expansion", nil, jsonBody(objReq([]string{"expansion_id", "query"}, prop("expansion_id", strSchema()), prop("query", strSchema()), prop("max_results", map[string]any{"type": "integer", "minimum": 1, "maximum": 20, "default": 10})), true), obj(prop("papers", array(refSchema("AcademicPaperRef"))), prop("source", strSchema()), prop("mock", boolSchema())))},
		"/academic/imports:preview":                   map[string]any{"post": operation("Preview reference or identifier import into the current collection", nil, jsonBody(objReq([]string{"target_dataset_id"}, prop("target_dataset_id", strSchema()), prop("identifier", strSchema()), prop("papers", array(refSchema("PaperLibraryPaper"))), prop("expansion_id", strSchema()), prop("work_ids", array(strSchema())), prop("works", array(obj())), prop("reference_ids", array(strSchema())), prop("source_document_ids", array(strSchema())), prop("resolve_external", boolSchema())), true), refSchema("AcademicImportPreview"))},
		"/academic/library":                           map[string]any{"get": operation("Read paper entries, logical folders and active materials", libraryParams(), nil, refSchema("PaperLibraryResponse"))},
		"/academic/library/papers/{library_paper_id}": map[string]any{"patch": operation("Update one paper with its revision and validate every active attachment", libraryParams("library_paper_id"), jsonBody(objReq([]string{"revision"}, prop("revision", int64Schema()), prop("metadata", refSchema("PaperLibraryMetadata")), prop("status", enumStringSchema("unread", "reading", "read")), prop("tags", array(strSchema()))), true), refSchema("PaperLibraryChanges"))},
		"/academic/library/papers:move":               map[string]any{"post": operation("Atomically move selected paper entries without moving files", libraryParams(), jsonBody(objReq([]string{"items", "folder_id"}, prop("items", array(refSchema("PaperLibraryTarget"))), prop("folder_id", strSchema())), true), refSchema("PaperLibraryChanges"))},
		"/academic/library/papers:remove":             map[string]any{"post": operation("Atomically remove selected entries while retaining materials and history", libraryParams(), jsonBody(objReq([]string{"items"}, prop("items", array(refSchema("PaperLibraryTarget")))), true), refSchema("PaperLibraryChanges"))},
		"/academic/library/papers/{library_paper_id}/attachments/{attachment_id}:detach": map[string]any{"post": operation("Detach a material without deleting its original or scholarly file facts", libraryParams("library_paper_id", "attachment_id"), jsonBody(objReq([]string{"revision"}, prop("revision", int64Schema())), true), refSchema("PaperLibraryChanges"))},
		"/academic/library/papers/{library_paper_id}/notes":                              map[string]any{"post": operation("Add a note idempotently by stable note ID", libraryParams("library_paper_id"), jsonBody(objReq([]string{"id", "content"}, prop("id", strSchema()), prop("content", strSchema())), true), refSchema("PaperLibraryChanges"))},
		"/academic/library/folders":                                                      map[string]any{"post": operation("Create a logical paper-library folder", libraryParams(), jsonBody(objReq([]string{"id", "name"}, prop("id", strSchema()), prop("name", strSchema()), prop("parent_id", strSchema())), true), refSchema("PaperLibraryChanges"))},
		"/academic/library/folders/{folder_id}":                                          map[string]any{"patch": operation("Rename a logical folder with revision validation", libraryParams("folder_id"), jsonBody(objReq([]string{"revision", "name"}, prop("revision", int64Schema()), prop("name", strSchema())), true), refSchema("PaperLibraryChanges"))},
		"/academic/library/folders/{folder_id}:delete":                                   map[string]any{"post": operation("Delete a folder subtree and move its papers into the parent folder", libraryParams("folder_id"), jsonBody(objReq([]string{"revision"}, prop("revision", int64Schema())), true), refSchema("PaperLibraryChanges"))},
		"/academic/imports": map[string]any{
			"post": operation("Import bibliography or queued sources, or confirm an uploaded PDF in its existing operation", nil, body("AcademicImportCreate"), map[string]any{"oneOf": []any{refSchema("PaperLibraryChanges"), obj(prop("batch_id", strSchema()), prop("status", strSchema()))}}),
			"get":  operation("Read source-scoped imports or a page of import operations", queryParams(param("query", "view", false, enumStringSchema("operations")), param("query", "cursor", false, strSchema()), param("query", "limit", false, intSchema()), param("query", "target_dataset_id", false, strSchema()), param("query", "source_document_id", false, strSchema()), param("query", "conversation_id", false, strSchema()), param("query", "history_id", false, strSchema()), param("query", "task_id", false, strSchema()), param("query", "workflow_session_id", false, strSchema()), param("query", "work_display_key", false, strSchema())), nil, map[string]any{"oneOf": []any{objReq([]string{"items", "total"}, prop("items", array(refSchema("AcademicImportQueueItem"))), prop("total", intSchema())), objReq([]string{"items"}, prop("items", array(refSchema("AcademicSourceImportItem")))), obj(prop("items", array(refSchema("AcademicImportOperation"))), prop("next_cursor", strSchema()), prop("notification", obj(prop("active", intSchema()), prop("needs_action", intSchema()))))}})},
		"/academic/imports/{batch_id}":                       map[string]any{"get": operation("Read a batch or its complete operation summary and a page of items", queryParams(param("path", "batch_id", true, strSchema()), param("query", "view", false, enumStringSchema("operations")), param("query", "cursor", false, strSchema()), param("query", "limit", false, intSchema())), nil, map[string]any{"oneOf": []any{obj(prop("batch", obj()), prop("items", array(obj()))), obj(prop("operation", refSchema("AcademicImportOperation")), prop("items", array(refSchema("AcademicImportOperationItem"))), prop("next_cursor", strSchema()))}})},
		"/academic/paper-contents:read":                      map[string]any{"post": operation("Read real full text without importing; continue using cursor only", nil, body("AcademicContentRead"), refSchema("AcademicContentResponse"))},
		"/academic/paper-contents:retry":                     map[string]any{"post": operation("Retry failed full text download and parsing", nil, jsonBody(objReq([]string{"expansion_id", "paper_id"}, prop("expansion_id", strSchema()), prop("paper_id", strSchema())), true), obj(prop("status", strSchema())))},
		"/academic/expansions":                               map[string]any{"get": operation("List current user's expansion records", datasetQuery, nil, obj(prop("items", array(refSchema("AcademicExpansion")))))},
		"/academic/expansions/{expansion_id}/papers:resolve": map[string]any{"post": operation("Resolve registered expansion papers and version-scoped content metadata without full bodies", recordPath, jsonBody(objReq([]string{"paper_ids"}, prop("paper_ids", map[string]any{"type": "array", "items": strSchema(), "maxItems": 500})), true), refSchema("AcademicResolvedPapers"))},
		"/academic/expansions/{expansion_id}":                map[string]any{"get": operation("Read saved rounds, current papers, content states and Chat availability", recordPath, nil, obj(prop("record", refSchema("AcademicExpansion")), prop("rounds", array(obj())), prop("contents", array(obj())), prop("presence", array(refSchema("AcademicPresence"))), prop("paper_importance", map[string]any{"type": "object", "additionalProperties": boolSchema()}), prop("handoffs", array(obj())), prop("chat_status", enumStringSchema("available", "trashed", "deleted")))), "delete": operation("Confirm deletion of results and trash/cancel the expansion Chat", recordPath, jsonBody(objReq([]string{"confirm"}, prop("confirm", boolSchema())), true), obj(prop("deleted", boolSchema())))},
		"/academic/mock-handoffs/{handoff_id}:submit":        map[string]any{"post": operation("Acknowledge the frozen downstream input; PPT relay reads its saved reflection", queryParams(param("path", "handoff_id", true, strSchema())), jsonBody(obj(prop("reflection_markdown", strSchema())), true), obj(prop("status", strSchema()), prop("kind", strSchema()), prop("input", refSchema("AcademicHandoffInput")), prop("papers", array(refSchema("AcademicPaperRef"))), prop("reflection_markdown", strSchema()), prop("feedback", strSchema())))},
		"/academic/chat-context":                             map[string]any{"get": operation("Read owned academic Chat progress and complete frozen handoff", queryParams(param("query", "conversation_id", true, strSchema())), nil, obj(prop("kind", strSchema()), prop("handoff_id", strSchema()), prop("input", refSchema("AcademicHandoffInput")), prop("contents", map[string]any{"oneOf": []any{obj(), array(obj())}}), prop("expansion_id", strSchema()), prop("dataset_id", strSchema()), prop("status", strSchema()), prop("version", int64Schema()), prop("source_available", boolSchema()), prop("next_conversation_id", strSchema()), prop("source_conversation_id", strSchema()), prop("ready_count", intSchema()), prop("paper_count", intSchema())))},
	}
}

func libraryParams(names ...string) []map[string]any {
	values := queryParams(param("query", "target_dataset_id", true, strSchema()))
	for _, name := range names {
		values = append(values, param("path", name, true, strSchema()))
	}
	return values
}
